//! `catalog.json` as generated by hub (`hub/catalog/SCHEMA.md`): types,
//! fetching with a short-lived cache, and the schema_version check.

use std::collections::BTreeMap;
use std::path::Path;
use std::time::{Duration, SystemTime};

use anyhow::{Context, Result};
use serde::Deserialize;

pub const SCHEMA_VERSION: u32 = 1;
/// Where hub publishes the catalog (served by hub/site/_redirects from
/// data/catalog.json, which the website reads); override with AV_CATALOG_URL.
/// Lera uses the same default to find av's cache file (see `cache_file`).
pub const DEFAULT_CATALOG_URL: &str = "https://asciiverse.sh/catalog.json";
const CACHE_TTL: Duration = Duration::from_secs(60 * 60);

/// The one HTTP agent for the catalog, casts and downloads. ureq waits
/// forever by default, so a host that drops packets (a parked domain, a
/// dead Wi-Fi) froze av on a blank screen; these give up on connecting and
/// on a silent server, and leave reading the body alone, however long a
/// big download takes.
pub fn http() -> &'static ureq::Agent {
    static AGENT: std::sync::OnceLock<ureq::Agent> = std::sync::OnceLock::new();
    AGENT.get_or_init(|| {
        let s = |n| Some(Duration::from_secs(n));
        ureq::Agent::config_builder()
            .timeout_resolve(s(5))
            .timeout_connect(s(5))
            .timeout_send_request(s(10))
            .timeout_recv_response(s(15))
            .build()
            .into()
    })
}

/// A parsed catalog. Built title by title (see `parse`), so one bad entry
/// is skipped instead of failing the lot.
#[derive(Debug, Default)]
pub struct Catalog {
    pub titles: BTreeMap<String, Title>,
    /// upstream projects holding several games, each game its own title
    pub collections: BTreeMap<String, Collection>,
    /// the latest av, so an older one can say it is out of date
    pub av: Option<AvRelease>,
}

/// The catalog's top-level `av` entry: av's latest release.
#[derive(Debug, Clone, Default)]
pub struct AvRelease {
    pub version: String,
    pub date: String,
    /// what is new in it, in the page's Markdown subset
    pub notes: String,
}

#[derive(Debug, Clone, Default, Deserialize)]
#[serde(default)]
pub struct Collection {
    pub name: String,
    pub url: String,
    pub description: String,
}

pub type Collections = BTreeMap<String, Collection>;

/// Where a title's group sits in the list: its kind's place, and titles no
/// longer in the catalog after all of them.
pub fn rank(t: &Title) -> u8 {
    if t.gone { u8::MAX } else { kind_rank(&t.kind) }
}

/// Put together each title's search text once, at load, so a search
/// doesn't lowercase the whole catalog on every frame. Fields are kept
/// apart by a newline, so no match runs from one into the next.
pub fn index(titles: &mut [Title], cols: &Collections) {
    for t in titles {
        let mut parts = vec![t.title.as_str(), t.id.as_str(), t.description.as_str()];
        parts.extend(t.topics.iter().map(String::as_str));
        parts.extend(t.genre.as_deref());
        parts.extend(t.developer.as_ref().map(|d| d.name.as_str()));
        parts.extend(t.collection.as_deref());
        let name = t.collection_name(cols).map(str::to_string);
        parts.extend(name.as_deref());
        t.haystack = parts.join("\n").to_lowercase();
    }
}

/// The list's order: by group, alphabetical within each.
pub fn sort(titles: &mut [Title]) {
    titles.sort_by_cached_key(|t| (rank(t), t.title.to_lowercase()));
}

/// Installed titles the catalog no longer lists, as titles of their own, so
/// they can still be played and uninstalled: what installed.json knows of
/// them, started as they were installed.
pub fn gone(titles: &BTreeMap<String, Title>, installed: &BTreeMap<String, crate::state::Installed>) -> Vec<Title> {
    installed
        .values()
        .filter(|i| !titles.contains_key(&i.id) && !titles.values().any(|t| t.id == i.id))
        .map(|i| {
            let mut t = Title {
                id: i.id.clone(),
                kind: if i.kind.is_empty() { "game".into() } else { i.kind.clone() },
                title: i.id.clone(),
                description: "No longer in the catalog. It stays playable here until you uninstall it.".into(),
                version: i.version.clone(),
                gone: true,
                ..Default::default()
            };
            t.exec.args = i.args.clone();
            if !i.exec.is_empty() {
                t.exec.names.insert(t.kind.clone(), serde_json::Value::String(i.exec.clone()));
            }
            t
        })
        .collect()
}

/// Where a kind's group sits in the list: games first, then text adventures,
/// programs, art and demos, movies, MUDs last
pub fn kind_rank(kind: &str) -> u8 {
    match kind {
        "game" => 0,
        "adventure" => 1,
        "program" => 2,
        "art" => 3,
        "movie" => 4,
        "mud" => 5,
        _ => 6,
    }
}

#[derive(Debug, Clone, Default, Deserialize)]
#[serde(default)]
pub struct Title {
    pub id: String,
    pub kind: String,
    pub title: String,
    pub description: String,
    pub license: String,
    pub repo: Option<String>,
    pub topics: Vec<String>,
    pub genre: Option<String>,
    pub funding: Option<String>,
    pub developer: Option<Person>,
    pub upstream: Option<Person>,
    // where it comes from and by whom, and the path in `repo` listing what Asciiverse changed
    pub provenance: Option<String>,
    pub changes: Option<String>,
    // the collection this game comes from, a key in Catalog::collections
    pub collection: Option<String>,
    pub exec: Exec,
    pub min_terminal: Option<Size>,
    pub requires: Requires,
    pub system_deps: Vec<String>,
    pub page: String,
    pub version: String,
    pub updated_at: String,
    pub cast_url: Option<String>,
    pub thumbnail_at: Option<f64>,
    pub platforms: BTreeMap<String, Platform>,
    /// release notes, newest first: the GitHub Release bodies, or the `CHANGELOG`
    pub news: Vec<News>,
    // MUDs (proposed kind = "mud"): a world on someone's server
    pub connect: Option<Connect>,
    pub since: Option<u32>,
    pub website: Option<String>,
    // storefront curation (the OLD! and NEW! banners); no field in SCHEMA.md yet
    pub old: bool,
    pub new: bool,
    /// installed, but no longer in the catalog (see `gone`); not a catalog field
    #[serde(skip)]
    pub gone: bool,
    /// everything search looks at, lowercased once (see `index`)
    #[serde(skip)]
    pub haystack: String,
}

/// `[exec]`: the binary to run, named by kind (`game = "greed"`), the
/// arguments av passes when it launches it (`args = ["-f"]`), and
/// `stderr = "terminal"` for a title that draws on stderr or needs it to be
/// the terminal (otherwise av sends stderr to the title's log).
#[derive(Debug, Clone, Default, Deserialize)]
pub struct Exec {
    #[serde(default)]
    pub args: Vec<String>,
    #[serde(default)]
    pub stderr: Option<String>,
    #[serde(flatten)]
    pub names: BTreeMap<String, serde_json::Value>,
}

#[derive(Debug, Clone, Default, Deserialize)]
#[serde(default)]
pub struct Person {
    pub name: String,
    pub url: String,
}

#[derive(Debug, Clone, Copy, Default, Deserialize)]
pub struct Size {
    pub cols: u16,
    pub rows: u16,
}

#[derive(Debug, Clone, Default, Deserialize)]
#[serde(default)]
pub struct Requires {
    pub utf8: bool,
    pub color: String,
    pub mouse: bool,
    pub gamepad: bool,
    pub glyphs: Vec<String>,
}

/// One release's notes, in the page's Markdown subset.
#[derive(Debug, Clone, Default, Deserialize)]
#[serde(default)]
pub struct News {
    pub version: String,
    /// `YYYY-MM-DD`, or empty
    pub date: String,
    pub notes: String,
}

#[derive(Debug, Clone, Deserialize)]
pub struct Platform {
    pub url: String,
    pub sha256: String,
    #[serde(default)]
    pub size: u64,
}

#[derive(Debug, Clone, Deserialize)]
pub struct Connect {
    pub host: String,
    pub port: u16,
}

impl Title {
    /// The binary inside the install dir: `[exec]` names it, else the id.
    pub fn exec_name(&self) -> String {
        let base = self.exec.names.values().find_map(|v| v.as_str().map(String::from)).unwrap_or_else(|| self.id.clone());
        if cfg!(windows) && !base.to_lowercase().ends_with(".exe") { format!("{base}.exe") } else { base }
    }

    /// The display name of the collection this game comes from.
    pub fn collection_name<'a>(&'a self, cols: &'a Collections) -> Option<&'a str> {
        self.collection.as_ref().map(|k| cols.get(k).map(|c| c.name.as_str()).unwrap_or(k.as_str()))
    }

    /// Whether a search (already lowercased) finds this title: name, topics,
    /// genre, developer, collection or description. An empty search finds
    /// everything.
    /// Whether a lowercased search matches: name, id, topics, genre,
    /// developer, description or collection, as put together by `index`.
    pub fn matches(&self, f: &str) -> bool {
        f.is_empty() || self.haystack.contains(f)
    }

    pub fn is_mud(&self) -> bool {
        self.kind == "mud"
    }
}

/// Rust target triples that can run on this machine, best first.
pub fn host_targets() -> Vec<&'static str> {
    match (std::env::consts::OS, std::env::consts::ARCH) {
        ("linux", "x86_64") => vec!["x86_64-unknown-linux-musl", "x86_64-unknown-linux-gnu"],
        ("linux", "aarch64") => vec!["aarch64-unknown-linux-musl", "aarch64-unknown-linux-gnu"],
        ("macos", "aarch64") => vec!["aarch64-apple-darwin", "x86_64-apple-darwin"],
        ("macos", "x86_64") => vec!["x86_64-apple-darwin"],
        ("windows", "x86_64") => vec!["x86_64-pc-windows-msvc", "x86_64-pc-windows-gnu"],
        // Windows 11 on ARM runs x86_64 programs under its built-in emulation
        ("windows", "aarch64") => {
            vec!["aarch64-pc-windows-msvc", "aarch64-pc-windows-gnu", "x86_64-pc-windows-msvc", "x86_64-pc-windows-gnu"]
        }
        _ => vec![],
    }
}

/// The platform entry to install on this machine, if the title has one.
pub fn pick_platform(t: &Title) -> Option<(&'static str, &Platform)> {
    host_targets().into_iter().find_map(|tri| t.platforms.get(tri).map(|p| (tri, p)))
}

/// Resolve a URL from the catalog, which may be relative to the catalog itself.
pub fn resolve(base: &str, url: &str) -> String {
    if url.contains("://") {
        return url.to_string();
    }
    let dir = &base[..base.rfind('/').map(|i| i + 1).unwrap_or(base.len())];
    let root = base.find("://").and_then(|i| base[i + 3..].find('/').map(|j| &base[..i + 3 + j])).unwrap_or(base);
    match url.strip_prefix('/') {
        Some(abs) => format!("{root}/{abs}"),
        None => format!("{dir}{url}"),
    }
}

pub struct Loaded {
    pub catalog: Catalog,
    /// true when the network failed and the cached copy is shown
    pub offline: bool,
    /// set when the catalog at the address is too new for this av and its
    /// cached copy is shown instead: what to tell the player
    pub outdated: Option<String>,
}

/// The address av reads the catalog from.
pub fn url() -> String {
    std::env::var("AV_CATALOG_URL").unwrap_or_else(|_| DEFAULT_CATALOG_URL.into())
}

/// One cache file per catalog address, so a cache of one catalog is never
/// taken for another (pointing AV_CATALOG_URL elsewhere, offline or not).
///
/// This name is a contract: Lera (programs/lera, src/paths.rs) computes the
/// same `catalog-<fnv1a of the URL>.json` to read its list of MUDs from
/// av's cache. Change this, `fnv1a` or `DEFAULT_CATALOG_URL` and Lera needs
/// the same change.
pub(crate) fn cache_file(cache_dir: &Path, url: &str) -> std::path::PathBuf {
    cache_dir.join(format!("catalog-{:016x}.json", fnv1a(url)))
}

/// FNV-1a, a short stable hash for file names, without another dependency.
pub fn fnv1a(s: &str) -> u64 {
    s.bytes().fold(0xcbf2_9ce4_8422_2325, |h, b| (h ^ b as u64).wrapping_mul(0x0100_0000_01b3))
}

enum Parsed {
    Ok(Catalog),
    /// a schema this av doesn't read; the `av` entry is still read, to name the av that does
    TooNew { schema: u64, av: Option<AvRelease> },
}

/// av's own entry, taken field by field: a missing, null or odd field must
/// never stop the catalog from loading.
fn av_entry(v: &serde_json::Value) -> Option<AvRelease> {
    let o = v.get("av")?.as_object()?;
    let field = |k: &str| o.get(k).and_then(|x| x.as_str()).map(|x| x.trim().to_string()).unwrap_or_default();
    let version = field("version");
    (!version.is_empty()).then(|| AvRelease { version, date: field("date"), notes: field("notes") })
}

/// Why a title can't be offered safely, if it can't: its id and kind name
/// folders, its exec a file inside its own, a MUD's host is a telnet argument.
fn unsafe_reason(t: &Title) -> Option<String> {
    let name = |s: &str| !s.is_empty() && s.bytes().all(|b| b.is_ascii_lowercase() || b.is_ascii_digit() || b == b'-');
    if !name(&t.id) {
        return Some(format!("id {:?} is not lowercase letters, digits and dashes", t.id));
    }
    if !name(&t.kind) {
        return Some(format!("kind {:?} is not lowercase letters, digits and dashes", t.kind));
    }
    let exec = t.exec_name();
    if exec.contains(['/', '\\']) || exec.starts_with('.') {
        return Some(format!("exec {exec:?} is not a plain file name"));
    }
    if let Some(c) = &t.connect
        && (c.host.starts_with('-') || c.host.contains(char::is_whitespace))
    {
        return Some(format!("host {:?} is not a host name", c.host));
    }
    None
}

fn parse(body: &str) -> Result<Parsed> {
    let v: serde_json::Value = serde_json::from_str(body).context("catalog.json is not valid JSON")?;
    let av = av_entry(&v);
    let schema = v.get("schema_version").and_then(|s| s.as_u64()).context("catalog.json has no schema_version")?;
    if schema != SCHEMA_VERSION as u64 {
        return Ok(Parsed::TooNew { schema, av });
    }
    let mut titles = BTreeMap::new();
    for (key, t) in v.get("titles").and_then(|t| t.as_object()).into_iter().flatten() {
        match serde_json::from_value::<Title>(t.clone()) {
            Ok(t) => match unsafe_reason(&t) {
                None => {
                    titles.insert(key.clone(), t);
                }
                Some(why) => log::warn!("catalog: skipped {key}: {why}"),
            },
            Err(e) => log::warn!("catalog: skipped {key}: {e}"),
        }
    }
    let mut collections = BTreeMap::new();
    for (key, c) in v.get("collections").and_then(|c| c.as_object()).into_iter().flatten() {
        match serde_json::from_value::<Collection>(c.clone()) {
            Ok(c) => {
                collections.insert(key.clone(), c);
            }
            Err(e) => log::warn!("catalog: skipped collection {key}: {e}"),
        }
    }
    Ok(Parsed::Ok(Catalog { titles, collections, av }))
}

/// What to say when the catalog is too new: which schema, the av that reads
/// it when the catalog names one, and how to update.
fn too_new(schema: u64, av: Option<&AvRelease>) -> String {
    let which = av.map(|r| format!(" av {} reads it.", r.version)).unwrap_or_default();
    format!(
        "The catalog is newer than this av understands (schema {schema}, av {} reads {SCHEMA_VERSION}).{which}\nUpdate av with:\n\n  {}",
        env!("CARGO_PKG_VERSION"),
        crate::selfupdate::how()
    )
}

fn read_cache(file: &Path) -> Option<Catalog> {
    match parse(&std::fs::read_to_string(file).ok()?) {
        Ok(Parsed::Ok(c)) => Some(c),
        _ => None,
    }
}

/// The cached catalog for `url` however old, without touching the network
/// (for tab completion). None when there is none or it can't be read.
pub fn cached(cache_dir: &Path, url: &str) -> Option<Catalog> {
    read_cache(&cache_file(cache_dir, url))
}

/// Fetch the catalog, using the cache when it is fresh and when offline.
pub fn load(url: &str, cache_dir: &Path, force: bool) -> Result<Loaded> {
    let cache = cache_file(cache_dir, url);
    // before the cache was kept per address: one file for whichever catalog
    for old in ["catalog.json", "catalog.url"] {
        let _ = std::fs::remove_file(cache_dir.join(old));
    }
    let fresh = std::fs::metadata(&cache)
        .and_then(|m| m.modified())
        .is_ok_and(|t| SystemTime::now().duration_since(t).unwrap_or_default() < CACHE_TTL);
    if fresh && !force {
        if let Some(catalog) = read_cache(&cache) {
            log::info!("catalog from cache {}", cache.display());
            return Ok(Loaded { catalog, offline: false, outdated: None });
        }
        log::warn!("the cached catalog can't be read; fetching it again");
    }
    let fetched = fetch(url).and_then(|body| Ok((parse(&body)?, body)));
    match fetched {
        Ok((Parsed::Ok(catalog), body)) => {
            crate::state::write_atomic(&cache, &body)?;
            log::info!("catalog fetched from {url}: {} titles", catalog.titles.len());
            Ok(Loaded { catalog, offline: false, outdated: None })
        }
        Ok((Parsed::TooNew { schema, av }, _)) => {
            // keep the library working from the last catalog this av read
            let msg = too_new(schema, av.as_ref());
            log::warn!("catalog schema {schema} is too new");
            let mut catalog = read_cache(&cache).with_context(|| msg.clone())?;
            catalog.av = av.or(catalog.av);
            Ok(Loaded { catalog, offline: false, outdated: Some(msg) })
        }
        Err(e) => {
            log::warn!("catalog fetch failed: {e:#}");
            let catalog = read_cache(&cache).with_context(|| format!("cannot reach {url}, and there is no cached copy of it"))?;
            Ok(Loaded { catalog, offline: true, outdated: None })
        }
    }
}

/// A small file from the network (the catalog, a preview), given up on
/// when it stops coming.
pub fn get_text(url: &str, limit: u64) -> Result<String> {
    let mut resp = http().get(url).config().timeout_recv_body(Some(Duration::from_secs(60))).build().call()?;
    Ok(resp.body_mut().with_config().limit(limit).read_to_string()?)
}

fn fetch(url: &str) -> Result<String> {
    get_text(url, 64 << 20)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn resolves_relative_urls() {
        let b = "http://127.0.0.1:8765/data/catalog.json";
        assert_eq!(resolve(b, "casts/x.cast"), "http://127.0.0.1:8765/data/casts/x.cast");
        assert_eq!(resolve(b, "/casts/x.cast"), "http://127.0.0.1:8765/casts/x.cast");
        assert_eq!(resolve(b, "https://e.org/a"), "https://e.org/a");
    }

    #[test]
    fn exec_name_and_args() {
        let t: Title = serde_json::from_str(r#"{"id":"greed","exec":{"game":"greed","args":["-f"]}}"#).unwrap();
        assert_eq!(t.exec.args, vec!["-f"]);
        assert!(t.exec_name().starts_with("greed"));
        let t: Title = serde_json::from_str(r#"{"id":"solitty"}"#).unwrap();
        assert!(t.exec_name().starts_with("solitty"));
        assert_eq!(t.exec.stderr, None);
    }

    #[test]
    fn stderr_on_the_terminal_is_not_taken_for_the_binary() {
        let t: Title = serde_json::from_str(r#"{"id":"warp","exec":{"stderr":"terminal","game":"warp"}}"#).unwrap();
        assert_eq!(t.exec.stderr.as_deref(), Some("terminal"));
        assert!(t.exec_name().starts_with("warp"));
    }

    fn catalog(body: &str) -> Catalog {
        match parse(body).unwrap() {
            Parsed::Ok(c) => c,
            Parsed::TooNew { .. } => panic!("too new"),
        }
    }

    #[test]
    fn a_newer_schema_is_told_apart_and_still_names_the_av() {
        let body = r#"{"schema_version": 2, "titles": {}, "av": {"version": "2.0.0"}}"#;
        let Parsed::TooNew { schema, av } = parse(body).unwrap() else { panic!("read a schema 2 catalog") };
        assert_eq!((schema, av.as_ref().map(|r| r.version.as_str())), (2, Some("2.0.0")));
        let msg = too_new(schema, av.as_ref());
        assert!(msg.contains("schema 2") && msg.contains("av 2.0.0 reads it"), "{msg}");
        assert!(msg.contains("install") || msg.contains("cargo"), "{msg}");
    }

    #[test]
    fn reads_the_latest_av_whatever_its_fields() {
        let c = catalog(r#"{"schema_version": 1, "titles": {}, "av": {"version": " 1.0.0 ", "notes": "- New"}}"#);
        assert_eq!(c.av.unwrap().version, "1.0.0");
        // a release without notes comes from GitHub as null; it must not stop the catalog
        let c = catalog(r#"{"schema_version": 1, "titles": {}, "av": {"version": "1.0.0", "date": null, "notes": null}}"#);
        assert_eq!(c.av.unwrap().notes, "");
        assert!(catalog(r#"{"schema_version": 1, "titles": {}, "av": null}"#).av.is_none());
        assert!(catalog(r#"{"schema_version": 1, "titles": {}, "av": {"version": 3}}"#).av.is_none());
        assert!(catalog(r#"{"schema_version": 1, "titles": {}}"#).av.is_none());
    }

    #[test]
    fn a_bad_or_unsafe_title_is_skipped_not_the_catalog() {
        let c = catalog(
            r#"{"schema_version": 1, "titles": {
                "good": {"id": "good", "kind": "game"},
                "broken": {"id": "broken", "kind": "game", "min_terminal": {"cols": 57}},
                "empty": {"id": "", "kind": "game"},
                "up": {"id": "..", "kind": "game"},
                "path": {"id": "path", "kind": "game", "exec": {"game": "../../bin/sh"}},
                "mud": {"id": "mud", "kind": "mud", "connect": {"host": "-oProxyCommand=x", "port": 23}}
            }}"#,
        );
        assert_eq!(c.titles.keys().collect::<Vec<_>>(), ["good"]);
    }

    #[test]
    fn installed_titles_the_catalog_dropped_stay_listed() {
        use crate::state::Installed;
        let titles = catalog(r#"{"schema_version": 1, "titles": {"kept": {"id": "kept", "kind": "game"}}}"#).titles;
        let inst = |id: &str, exec: &str| Installed {
            id: id.into(),
            version: "1.0".into(),
            sha256: String::new(),
            installed_at: String::new(),
            kind: "program".into(),
            target: String::new(),
            exec: exec.into(),
            args: vec!["-f".into()],
        };
        let installed = BTreeMap::from([("kept".to_string(), inst("kept", "")), ("old".to_string(), inst("old", "oldbin"))]);
        let gone = gone(&titles, &installed);
        assert_eq!(gone.len(), 1);
        let t = &gone[0];
        assert!(t.gone && t.id == "old" && t.kind == "program" && t.version == "1.0");
        assert!(t.exec_name().starts_with("oldbin"), "started as it was installed");
        assert_eq!(t.exec.args, ["-f"]);
        // and they sort after every kind
        let mut all: Vec<Title> = titles.into_values().chain(gone).collect();
        all.reverse();
        sort(&mut all);
        assert_eq!(all.last().unwrap().id, "old");
    }

    #[test]
    fn the_cache_belongs_to_its_address() {
        use crate::testutil::serve;
        use std::collections::BTreeMap;
        let dir = std::env::temp_dir().join(format!("av-catalog-cache-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        let one = |id: &str| format!(r#"{{"schema_version": 1, "titles": {{"{id}": {{"id": "{id}", "kind": "game"}}}}}}"#).into_bytes();
        let base = serve(BTreeMap::from([("/a.json".to_string(), one("a")), ("/b.json".to_string(), one("b")), ("/new.json".to_string(), br#"{"schema_version": 9, "titles": {}, "av": {"version": "9.0.0"}}"#.to_vec())]));
        let (a, b) = (format!("{base}/a.json"), format!("{base}/b.json"));
        let ids = |l: &Loaded| l.catalog.titles.keys().cloned().collect::<Vec<_>>();

        assert_eq!(ids(&load(&a, &dir, false).unwrap()), ["a"]);
        // another address within the hour gets its own catalog, not a's cache
        assert_eq!(ids(&load(&b, &dir, false).unwrap()), ["b"]);
        // offline, an address with no cache of its own says so instead of showing another's
        let dead = "http://127.0.0.1:9/c.json";
        assert!(load(dead, &dir, false).is_err());
        assert!(cached(&dir, dead).is_none());
        assert_eq!(cached(&dir, &a).map(|c| c.titles.len()), Some(1));

        // a cache cut short is fetched again, not an error for an hour
        std::fs::write(cache_file(&dir, &a), "{\"schema_version\": 1, \"tit").unwrap();
        assert_eq!(ids(&load(&a, &dir, false).unwrap()), ["a"]);

        // a catalog too new for this av: the last one it read, marked so
        let new = format!("{base}/new.json");
        std::fs::copy(cache_file(&dir, &a), cache_file(&dir, &new)).unwrap();
        let l = load(&new, &dir, true).unwrap();
        assert_eq!(ids(&l), ["a"]);
        assert!(l.outdated.unwrap().contains("schema 9"));
        assert_eq!(l.catalog.av.unwrap().version, "9.0.0");
        let _ = std::fs::remove_dir_all(&dir);
    }
}
